changeSet.sql:
DO $change$
DECLARE
    previous_sql TEXT;
    corrected_sql TEXT;
BEGIN
    SELECT report_sql INTO previous_sql
      FROM stretchy_report
     WHERE report_name='Informe Auxiliar de Mayor';
    IF previous_sql IS NULL THEN
        RAISE EXCEPTION 'Informe Auxiliar de Mayor report is not registered';
    END IF;
    corrected_sql := replace(previous_sql,
        $fallback$NULLIF(BTRIM(source_line.source_movement_reference), ''),$fallback$,
        '');
    IF corrected_sql = previous_sql THEN
        RAISE EXCEPTION 'Expected bank-book ID fallback was not found in Informe Auxiliar de Mayor';
    END IF;
    UPDATE stretchy_report SET report_sql=corrected_sql
     WHERE report_name='Informe Auxiliar de Mayor';
END
$change$;
